{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'segments' not in case or 'budget' not in case:
        raise ValueError("case must contain 'segments' and 'budget'")
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments)==0:
        raise ValueError("segments must be a non-empty list")
    if not isinstance(budget, int):
        raise ValueError("budget must be an integer")
    for seg in segments:
        if not isinstance(seg, dict):
            raise ValueError("each segment must be a dict")
        for key in ('name','importance','minimum','capacity'):
            if key not in seg:
                raise ValueError(f"segment missing key {key}")
            if not isinstance(seg[key], int):
                raise ValueError(f"segment.{key} must be integer")
    sum_min = sum(seg['minimum'] for seg in segments)
    sum_cap = sum(seg['capacity'] for seg in segments)
    if budget < sum_min:
        raise ValueError(f"budget {budget} < sum of minimums {sum_min}")
    if budget > sum_cap:
        raise ValueError(f"budget {budget} > sum of capacities {sum_cap}")
    allocations = [seg['minimum'] for seg in segments]
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = 0
        best_num = segments[0]['importance']
        best_denom = allocations[0] + 1
        for i in range(1, len(segments)):
            num = segments[i]['importance']
            denom = allocations[i] + 1
            if num * best_denom > best_num * denom:
                best_idx = i
                best_num = num
                best_denom = denom
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = allocations[i]
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": budget
    }"}
